"""Reverse Nodes in k-Group — reverse each full block, leave the remainder.

`group_prev` always points at the node before the block being reversed.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def reverseKGroup(self, head, k: int):
        sentinel = ListNode(0, head)
        group_prev = sentinel
        while True:
            kth = group_prev
            for _ in range(k):
                kth = kth.next
                if not kth:
                    return sentinel.next
            group_next = kth.next

            prev, node = group_next, group_prev.next
            while node is not group_next:
                node.next, prev, node = prev, node, node.next

            new_tail = group_prev.next
            group_prev.next = kth
            group_prev = new_tail
